import type { Metadata, Viewport } from "next";
import { Plus_Jakarta_Sans } from "next/font/google";
import localFont from "next/font/local";
import "./globals.css";
import { profile } from "@/content/profile";
import { jsonLdString, keywords, siteDescription, siteJsonLd, siteTitle, siteUrl } from "@/lib/seo";
import { Providers } from "@/components/Providers";
import { Navbar } from "@/components/ui/Navbar";
import { LoadingScreen } from "@/components/ui/LoadingScreen";

// Display + Japanese fonts are glyph subsets of the Google Fonts originals (OFL),
// generated by `npm run fonts`, so they cost ~40 KB instead of hundreds.
const dela = localFont({
  src: "../assets/fonts/dela-gothic-one-latin.woff2",
  weight: "400",
  display: "swap",
  variable: "--font-dela",
});
const zen = localFont({
  src: "../assets/fonts/zen-kaku-gothic-new-700-subset.woff2",
  weight: "700",
  display: "swap",
  variable: "--font-zen",
});
const jakarta = Plus_Jakarta_Sans({
  subsets: ["latin"],
  display: "swap",
  variable: "--font-jakarta",
});

export const metadata: Metadata = {
  metadataBase: new URL(siteUrl),
  title: { default: siteTitle, template: `%s | ${profile.name}` },
  description: siteDescription,
  keywords,
  authors: [{ name: profile.name, url: siteUrl }],
  creator: profile.name,
  alternates: { canonical: "/" },
  openGraph: {
    type: "website",
    locale: "id_ID",
    url: "/",
    siteName: `${profile.name} Portfolio`,
    title: siteTitle,
    description: siteDescription,
  },
  twitter: { card: "summary_large_image", title: siteTitle, description: siteDescription },
  robots: {
    index: true,
    follow: true,
    googleBot: { index: true, follow: true, "max-image-preview": "large" },
  },
  formatDetection: { telephone: false },
};

export const viewport: Viewport = {
  themeColor: "#0B0B14",
  colorScheme: "dark",
  width: "device-width",
  initialScale: 1,
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html
      lang="id"
      className={`${dela.variable} ${zen.variable} ${jakarta.variable}`}
      suppressHydrationWarning
    >
      <body>
        <script
          type="application/ld+json"
          dangerouslySetInnerHTML={{ __html: jsonLdString(siteJsonLd()) }}
        />
        <a
          href="#main"
          className="bg-paper text-ink sr-only z-[100] px-4 py-2 font-bold focus:not-sr-only focus:fixed focus:top-3 focus:left-3"
        >
          Langsung ke konten
        </a>
        <noscript>
          <style>{`.loader{display:none!important}`}</style>
        </noscript>
        <Providers>
          <LoadingScreen />
          <Navbar />
          {children}
        </Providers>
        <div className="grain" aria-hidden="true" />
        {/* Shared SVG filters (manga panel ripple). */}
        <svg width="0" height="0" aria-hidden="true" className="absolute">
          <filter id="ripple">
            <feTurbulence
              type="fractalNoise"
              baseFrequency="0.012 0.04"
              numOctaves="1"
              seed="3"
              result="noise"
            >
              <animate
                attributeName="baseFrequency"
                dur="6s"
                values="0.012 0.04;0.02 0.06;0.012 0.04"
                repeatCount="indefinite"
              />
            </feTurbulence>
            <feDisplacementMap in="SourceGraphic" in2="noise" scale="10" />
          </filter>
        </svg>
      </body>
    </html>
  );
}
